/* Same studio state, now connected to the local processing server. */
let processing=false,projectId=null,serviceReady=false,currentJob=null;
const stageSource=addVideo,renderStudio=render,oldDemo=demo;
const jobPanel=document.createElement('div');jobPanel.id='jobPanel';jobPanel.className='job-panel';jobPanel.hidden=true;jobPanel.innerHTML='<div><strong id="jobMessage" role="status">Reading video…</strong><span id="jobPercent"></span></div><progress id="jobProgress" max="100" value="0" aria-label="Video processing progress"></progress><p id="jobDetail">You can stay here while the studio finds your clips.</p>';$('importForm').after(jobPanel);
const submit=$('importForm').querySelector('button');submit.innerHTML='Find my clips <span>✧</span>';
$('setupBtn').textContent='Checking the local processor…';
$('sourceTitle').textContent='Paste a link to get started';$('sourceMeta').textContent='The studio reads the video and chooses timestamps for you.';
$('transcriptHint').textContent='Automatically retrieved words and timings. You can inspect or edit them here if you want.';
$('transcriptFile').accept='.srt,.vtt,.txt';
const details=document.createElement('details');details.className='transcript-details';details.innerHTML='<summary>Transcript & advanced editing <span>Optional</span></summary>';
const transcriptHeader=document.querySelector('.transcript-header');transcriptHeader.before(details);details.append(transcriptHeader,$('transcript'),$('transcriptHint'));
const statusNote=document.createElement('p');statusNote.className='automatic-note';statusNote.textContent='No timestamps needed. Paste a link and we’ll read the captions or transcribe the speech.';details.before(statusNote);
$('analyzeBtn').innerHTML='Refresh suggestions <span>↻</span>';
$('renderBtn').className='primary export render-video';$('renderBtn').textContent='Create MP4 clip ↓';$('exportBtn').before($('renderBtn'));
const downloadLink=document.createElement('a');downloadLink.id='videoDownload';downloadLink.className='primary export';downloadLink.hidden=true;downloadLink.textContent='Download your MP4 ↓';$('renderBtn').after(downloadLink);
const renderedPlayer=document.createElement('video');renderedPlayer.id='renderedPlayer';renderedPlayer.controls=true;renderedPlayer.playsInline=true;renderedPlayer.preload='metadata';renderedPlayer.hidden=true;renderedPlayer.setAttribute('aria-label','Your rendered clip');$('phone').append(renderedPlayer);
function showRendered(result){renderedPlayer.src=result.previewUrl||result.downloadUrl;renderedPlayer.hidden=false;$('phone').classList.add('has-render');$('jobDetail').textContent=result.qualityNote||'Watch your finished video, then download it.';}
function hideRendered(){renderedPlayer.pause();renderedPlayer.removeAttribute('src');renderedPlayer.load();renderedPlayer.hidden=true;$('phone').classList.remove('has-render');}
const previewBtn=document.createElement('button');previewBtn.className='caption-download';previewBtn.id='playSelection';previewBtn.textContent='Watch selected moment ↗';$('renderBtn').before(previewBtn);
const hint=document.createElement('p');hint.className='field-hint';hint.textContent='MP4 uses a 1080 × 1920 canvas, fills the background with your video, adds animated captions, and balances the audio.';$('renderBtn').after(hint);
$('phone').querySelector('.phone-bottom span:last-child').textContent='1080 × 1920';
document.querySelector('.pending-dot').style.background='var(--lime)';
document.querySelector('.page-heading p').textContent='Paste a link. We find the moments and choose the timestamps.';
function setBusy(busy){processing=busy;document.querySelectorAll('.swatch').forEach(el=>el.disabled=busy);for(const id of ['clipTitle','startTime','endTime','exportBtn','srtBtn'])$(id).disabled=busy||!selected();$('transcript').disabled=busy;submit.disabled=busy;$('demoBtn').disabled=busy;$('analyzeBtn').disabled=busy||!state.cues.length;$('renderBtn').disabled=busy||!projectId||!selected();$('clipLength').disabled=busy;$('videoUrl').disabled=busy;document.querySelector('.import-panel').setAttribute('aria-busy',String(busy));}
function showProgress(message,percent){jobPanel.hidden=false;$('jobMessage').textContent=message;$('jobProgress').value=percent;$('jobPercent').textContent=`${percent}%`;}
async function requestJSON(url,options){let response;try{response=await fetch(url,{...options,signal:AbortSignal.timeout(20000)})}catch{throw Error('The local processor is not responding. Open the Cutroom launcher, then try again.')}let data;try{data=await response.json()}catch{throw Error('Automatic processing needs the running studio server. Open http://127.0.0.1:4182 instead of the HTML file.')}if(!response.ok)throw Error(data.error||'The request could not be completed.');return data}
async function pollJob(id,maxPolls=57600){currentJob=id;for(let i=0;i<maxPolls;i++){const job=await requestJSON(`/api/jobs/${id}`);if(job.status==='failed')throw Error(job.error||'The video could not be processed.');if(job.status==='complete')return job.result;showProgress(job.progress,job.percent||3);await new Promise(r=>setTimeout(r,1500));}throw Error('This video is taking too long. Try again with a shorter video.')}
function toSrt(cues){return cues.map((c,i)=>`${i+1}\n${srtTime(c.start)} --> ${srtTime(c.end)}\n${c.text}\n`).join('\n')}
exportPlan=function(){if(!updateEdit())return;const c=selected();download(JSON.stringify({title:c.title,source:state.demo?'Illustrative demo':$('videoUrl').value.trim(),startSeconds:c.start,endSeconds:c.end,platform:$('platform').value,aspectRatio:'9:16',resolution:'1080x1920',framing:'Full source over a blurred motion background',captionStyle:state.style,transcript:c.text,potentialScore:c.score,scoreMethod:'Text-based editorial signals; not a views prediction',renderStatus:$('videoDownload').hidden?'Not rendered':'MP4 available in this studio session'},null,2),'cutroom-clip-plan.json','application/json')};
$('exportBtn').onclick=exportPlan;
addVideo=async function(url){if(processing)throw Error('Wait for the current video to finish.');const id=youtubeId(url);{const h=await requestJSON('/api/health');if(!h.ready)throw Error('The video processor cannot access its installed libraries. Restart it using Start-Cutroom; waiting alone will not fix this.');serviceReady=true}stageSource(url);projectId=null;state.demo=false;$('sourceMeta').textContent='Reading the video automatically…';$('transcript').placeholder='The transcript will appear here automatically.';$('importError').textContent='';$('videoDownload').hidden=true;setBusy(true);showProgress('Connecting to YouTube…',3);try{const job=await requestJSON('/api/analyze',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({url})});const result=await pollJob(job.id);projectId=job.id;state.cues=result.cues;$('transcript').value=toSrt(result.cues);$('sourceTitle').textContent=result.title;$('sourceMeta').textContent=`${result.method} · ${result.language.toUpperCase()} · ${stamp(result.duration)}`;try{findHighlights()}catch(e){if(!durationVerified)throw e;$('clipMode').value='whole';$('partCount').value=Math.min(10,Math.max(1,Math.floor(videoDuration)));findHighlights()}showProgress(`Ready — ${state.clips.length} moments found`,100);$('jobDetail').textContent='Your timestamps are ready. Select a moment, then create its MP4.';toast('Video read. Your clip ideas are ready.');return {videoId:id,projectId,clips:state.clips.length,method:result.method}}catch(e){$('importError').textContent=e.message;$('sourceMeta').textContent='This video could not be read.';showProgress('Couldn’t read this video',0);$('jobDetail').textContent=e.message;throw e}finally{setBusy(false)}};
render=function(){hideRendered();renderStudio();if(!state.clips.length)$('moments').innerHTML='<div class="empty-moments">Your best moments will appear here.<br>Paste a YouTube or Twitch clip link above. We’ll read the video and choose the timestamps.</div>';$('analyzeBtn').disabled=processing||!state.cues.length;$('renderBtn').disabled=processing||!projectId||!selected();$('playSelection').disabled=!state.videoId||!selected();$('videoDownload').hidden=true;};
grade=function(text,firstSeconds){const words=text.split(/\s+/),opening=firstSeconds??words.slice(0,22).join(' ');const hook=/\?|\b(secret|nobody|why|how|mistake|never|imagine|stop|surprising|actually)\b|what if|here's|most people|the problem/i.test(opening),value=/\b(because|learn|step|tip|trick|rule|means|example|solution|instead|change|start)\b/i.test(text),emotion=/\b(feel|love|fear|afraid|pain|happy|failed|failure|dream|believe|confidence|alone|surprised)\b/i.test(text),specific=/\b\d+\b|\b(first|second|three|two|million|percent)\b/i.test(text),complete=/[.!?]["']?$/.test(text.trim());const score=Math.min(92,34+Number(hook)*19+Number(value)*14+Number(emotion)*10+Number(specific)*8+Number(complete)*5+(words.length>=30&&words.length<=170?2:0));const signals=[hook?'a curiosity-led opening':null,value?'a practical idea':null,emotion?'emotional language':null,specific?'a concrete detail':null].filter(Boolean);return {score,reason:signals.length?'Text signals: '+signals.join(', ')+'.':'A possible story moment. Review whether it stands on its own.',type:hook?'Hook candidate':value?'Takeaway':'Story moment'};};
findHighlights=function(){try{const cues=parseTranscript($('transcript').value),target=Number($('clipLength').value),total=cues.at(-1).end-cues[0].start,minLength=Math.min(12,total*.65),candidates=[];for(let i=0;i<cues.length;i++){if(i&&cues[i].start-cues[i-1].start<2&&!/[.!?]$/.test(cues[i-1].text))continue;let j=i;while(j+1<cues.length&&cues[j+1].end-cues[i].start<=target)j++;if(j===i&&cues[i].end-cues[i].start>target+10)continue;const group=cues.slice(i,j+1),end=group.at(-1).end,duration=end-cues[i].start;if(duration<minLength)continue;const text=group.map(x=>x.text).join(' '),sentence=text.match(/^.{10,110}?[.!?](?:\s|$)/)?.[0]?.trim(),title=sentence||text.slice(0,95).replace(/\s+\S*$/,'')+'…';candidates.push({start:cues[i].start,end,text,title,...grade(text,group.filter(c=>c.start<cues[i].start+6).map(c=>c.text).join(" "))})}candidates.sort((a,b)=>b.score-a.score);const picks=[];for(const c of candidates){if(picks.every(p=>Math.max(0,Math.min(c.end,p.end)-Math.max(c.start,p.start))<=Math.min(c.end-c.start,p.end-p.start)*.1))picks.push(c);}if(!picks.length)throw Error('Not enough continuous speech was found to make a useful clip.');state.cues=cues;state.clips=picks;state.selected=0;$('analysisError').textContent='';render();return {count:picks.length,method:'Automatic transcript-based editorial scoring'}}catch(e){$('analysisError').textContent=e.message;throw e}};
$('importForm').onsubmit=async e=>{e.preventDefault();try{await addVideo($('videoUrl').value.trim())}catch(e){$('importError').textContent=e.message}};
$('renderBtn').onclick=async()=>{if(!projectId||!updateEdit())return;const c=selected();setBusy(true);$('editError').textContent='';$('videoDownload').hidden=true;try{const job=await requestJSON('/api/render',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({projectId,start:c.start,end:c.end,title:c.title,style:state.style})});const result=await pollJob(job.id,57600);$('videoDownload').href=result.downloadUrl;$('videoDownload').hidden=false;showProgress('Your MP4 is ready to download',100);showRendered(result);toast('Your vertical video is ready.')}catch(e){$('editError').textContent=e.message;showProgress('Couldn’t export this clip',0);$('jobDetail').textContent=e.message}finally{setBusy(false)}};
$('playSelection').onclick=()=>{const c=selected();if(c&&state.videoId)$('sourceScreen').innerHTML=`<iframe src="https://www.youtube-nocookie.com/embed/${state.videoId}?start=${Math.floor(c.start)}&end=${Math.ceil(c.end)}&autoplay=1" title="Selected YouTube moment" allow="autoplay; encrypted-media; picture-in-picture" allowfullscreen></iframe>`;$('sourceScreen').scrollIntoView({behavior:'smooth',block:'center'})};
info=function(kind){$('dialogContent').innerHTML=kind==='help'?'<h2>Paste a link. We’ll do the reading.</h2><ol><li><strong>Find my clips.</strong> For YouTube, the studio retrieves captions or transcribes the audio. For Twitch clip links, it downloads the clip and reads the speech locally.</li><li><strong>Review your moments.</strong> Timestamps and text-based potential scores are filled in for you. Watch any selection in the source player.</li><li><strong>Create MP4 clip.</strong> The studio downloads the source and renders a vertical video with captions. Download it when it’s ready.</li></ol><p>Caption styling and timing can be adjusted, but no manual timestamp entry is required. Scores are editorial signals, not view predictions.</p>':'<h2>Your local processing studio</h2><div class="connection-item"><strong>Automatic caption reading</strong><p>Reads available YouTube transcripts from your link. No API key is needed.</p></div><div class="connection-item"><strong>Speech transcription</strong><p>Uses a local speech model when captions aren’t available. The first use downloads the model and can take longer.</p></div><div class="connection-item"><strong>Vertical MP4 export</strong><p>Uses the best source up to 4K, exports in Full HD, fills the frame with a blurred motion background, and adds animated captions. Automatic face tracking is not included.</p></div><p>Paste a YouTube video link or a Twitch clip share link. Twitch imports include an original MP4 download. The processor runs on this computer. Either service may block private, restricted, deleted, or some public videos. Projects stay in this session; exported files are stored locally. No fixed source-duration cap. Long videos need more disk space and processing time.</p>';$('infoDialog').showModal()};
$('demoBtn').onclick=()=>{projectId=null;jobPanel.hidden=true;oldDemo();render()};
state={demo:false,videoId:null,clips:[],selected:0,cues:[],style:'lime'};$('transcript').value='';$('transcript').placeholder='We’ll fill this in automatically after reading the video.';$('sourceScreen').innerHTML='<div class="source-empty"><span>▶</span><strong>Your video goes here</strong><p>One link. No timestamps to enter.</p></div>';render();$('sessionTag').textContent='New project';
requestJSON('/api/health').then(h=>{serviceReady=h.ready;$('setupBtn').textContent=h.ready?'Automatic processing ready ↗':'Processor setup needed ↗'}).catch(()=>{$('setupBtn').textContent='Open the running studio to process videos ↗';$('importError').textContent='Open http://127.0.0.1:4182 to use automatic processing.'});

document.querySelectorAll('.swatch').forEach(button=>button.addEventListener('click',()=>{hideRendered();$('videoDownload').hidden=true;}));
